"""Production metadata and safe static-page behavior, shared by all builds."""
from html import escape
import os
ORIGIN='https://harnessloop.ai'
# Vercel context is authoritative: a Preview must never inherit a production override.
PRODUCTION=(os.environ.get('VERCEL_ENV')=='production') if 'VERCEL_ENV' in os.environ else os.environ.get('SITE_ENV')=='production'
DESCRIPTIONS={
 '':['为具体业务定制 AI Harness。连接数据、工具、质量标准与人工反馈，以独立验证推动受控改进。','Custom AI harnesses for your business. Connect data, tools, quality standards and human feedback for measured, controlled improvement.'],
 'how-it-works':['了解 HarnessLoop 的运行环与改进环：明确权限、保留证据、验证候选版本，再决定发布。','Explore execution and improvement loops: scoped permissions, traceable evidence, independent validation and controlled releases.'],
 'data-factory':['通过合成采购示例，了解资料抽取、来源定位、质量检查和候选改进如何组成数据与知识工厂。','A synthetic procurement example shows how extraction, source evidence, quality checks and candidate improvements form a data factory.'],
 'research':['HarnessLoop 实践笔记：双闭环设计、失败分类、独立评测与可追溯的版本改进。','HarnessLoop design notes on dual loops, failure classification, independent evaluation and traceable version improvement.'],
 'contact':['联系 HarnessLoop，讨论业务任务与验收标准。使用本地简报工具整理需求，再由你选择是否发送邮件。','Discuss your business task and acceptance criteria with HarnessLoop. Prepare a brief locally and choose whether to email it.'],
 'faq':['关于 AI Agent Harness、自进化工作流、RAG、独立评测和数据工厂的常见问题，了解 HarnessLoop 的合作方式与能力边界。','Answers about AI agent harnesses, controlled self-improvement, RAG, evaluation and data factories. Learn how to start a HarnessLoop project.'],
 'privacy':['了解 HarnessLoop 网站的本地简报、语言偏好、托管访问日志与邮件联系的数据处理范围。','Learn about local briefs, language preferences, hosting access logs and email contact on the HarnessLoop website.']}
def privacy(en):
 if en:return '''<div class="wrap subhero"><span class="eyebrow">PRIVACY</span><h1>Your information, in context.</h1><p class="micro">Updated 15 November 2026</p><h2>What this website does</h2><p class="lead">HarnessLoop is an informational website with synthetic demonstrations. It has no user accounts, payment processing or file uploads. Service scope and data handling for a client project are agreed separately before any project data is provided.</p><h2>A brief stays in your browser</h2><p>The brief tool generates text in the current page. It does not submit your input to a server, save it in cookies or local storage, or retain it after refresh or a language switch. Copying uses your browser clipboard. The email link opens your mail application with a draft; you decide whether to send it.</p><h2>Language preference and hosting</h2><p>Only the language choice is stored locally under harnessloop-language. You can clear it using your browser’s site-data settings. Chinese and English pages have stable URLs; use the language link to switch. This website does not include analytics trackers, advertising scripts, third-party fonts or an external form service. Hosting providers may process network and request information to serve and secure the website. For Vercel’s practices, see <a href="https://vercel.com/legal/privacy-policy" rel="noopener noreferrer" target="_blank">Vercel’s privacy notice</a>.</p><h2>When you email</h2><p>Messages you choose to send to contact@harnessloop.ai pass through email providers and are available to the recipient to review and respond to your enquiry. Email is separate from the local brief tool. Please do not send medical records, personal sensitive information, credentials or confidential client data. Agree a suitable data-sharing process before supplying project materials.</p><h2>Questions and requests</h2><p>For questions about this website or information you have sent, contact <a href="mailto:contact@harnessloop.ai">contact@harnessloop.ai</a>. Include only the information needed to identify your enquiry.</p></div>'''
 return '''<div class="wrap subhero"><span class="eyebrow">隐私说明</span><h1>清楚说明，<br>信息在哪里处理。</h1><p class="micro">更新于 2026 年 11 月 15 日</p><h2>本站的范围</h2><p class="lead">HarnessLoop 是业务介绍与合成演示网站，不提供用户账号、支付或文件上传。客户项目的服务范围与数据处理方式，应在提供项目数据前另行约定。</p><h2>简报只在浏览器中生成</h2><p>简报工具在当前页面中生成文字，不向服务器提交输入，不写入 Cookie 或本地存储，刷新或切换语言后不保留。复制功能使用浏览器剪贴板。邮件链接会在邮件客户端中打开草稿，是否发送由你决定。</p><h2>语言偏好与托管</h2><p>本站仅将语言选择保存在本地的 harnessloop-language 项中，可通过浏览器的网站数据设置清除。中英文页面各有固定网址，可通过语言链接切换。本站没有接入分析追踪、广告脚本、第三方字体或外部表单服务。托管服务商可能为提供网站和保障安全处理网络及访问请求信息。Vercel 的处理方式见其<a href="https://vercel.com/legal/privacy-policy" rel="noopener noreferrer" target="_blank">隐私说明</a>。</p><h2>当你主动发送邮件</h2><p>主动发送到 contact@harnessloop.ai 的邮件会经过邮件服务商处理，收件方可阅读并用于了解和回复你的咨询。这与本地简报工具是不同的处理过程。请勿发送病历、个人敏感信息、密码或客户机密；提供项目资料前，请先约定适当的数据交换方式。</p><h2>问题与请求</h2><p>如对本站或已发送的信息有疑问，请联系 <a href="mailto:contact@harnessloop.ai">contact@harnessloop.ai</a>，仅提供定位咨询所需的信息。</p></div>'''
def prepare(body,slug,en):
 if slug=='privacy':return privacy(en)
 body=body.replace('在每次反馈中进化。','以验证驱动持续进化。')
 if slug=='contact':
  body=body.replace('<form class="form" id="brief-form">','<div class="form" id="brief-form" role="group" aria-label="'+('Local brief tool' if en else '本地简报工具')+'">').replace('</form>','</div>')
  body=body.replace('type="submit"','type="button" id="generate-brief"')
  body=body.replace('name="task"','name="task" autocomplete="off"').replace('name="pain"','name="pain" autocomplete="off"').replace('name="criteria"','name="criteria" autocomplete="off"')
  body+='<noscript><p class="wrap notice">'+('JavaScript is unavailable. The brief tool is disabled; use the email address above to contact us. Nothing entered here is submitted.' if en else 'JavaScript 不可用，简报工具无法运行。请使用上方邮箱联系；这里填写的内容不会提交。')+'</p></noscript>'
 if slug=='data-factory':
  body=body.replace('id="demo-output"','id="demo-output"')
  body+='<noscript><p class="wrap notice">'+('Static example: the source says “15 business days”, but the baseline extracts “15 days”. A candidate keeps the original unit; independent validation is still required.' if en else '静态示例：原文为“15 个工作日”，基线误提取为“15 天”。候选版本保留原始单位，但仍需独立验证。')+'</p></noscript>'
 return body

def metadata(lang,slug,title):
 path=('/en/' if lang=='en' else '/')+(slug+'/' if slug else '')
 zh=ORIGIN+'/'+(slug+'/' if slug else '');en=ORIGIN+'/en/'+(slug+'/' if slug else '')
 desc=DESCRIPTIONS[slug][lang=='en'];url=ORIGIN+path
 from seo import structured
 return desc, structured(lang,slug,title,desc)+f'''<link rel="canonical" href="{url}"><link rel="alternate" hreflang="zh-CN" href="{zh}"><link rel="alternate" hreflang="en" href="{en}"><link rel="alternate" hreflang="x-default" href="{zh}"><meta property="og:type" content="website"><meta property="og:site_name" content="HarnessLoop"><meta property="og:title" content="{escape(title)} | HarnessLoop"><meta property="og:description" content="{escape(desc)}"><meta property="og:url" content="{url}"><meta property="og:locale" content="{'en_US' if lang=='en' else 'zh_CN'}"><meta property="og:image" content="{ORIGIN}/assets/social.png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="HarnessLoop: Business-specific AI harnesses"><meta name="twitter:image" content="{ORIGIN}/assets/social.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)} | HarnessLoop"><meta name="twitter:description" content="{escape(desc)}">'''
